#include <cstring>
#include <cmath>
#include <algorithm>

using namespace std;

typedef long long ll;

const double eps = 1e-6, pi = acos(-1);
const int N = 1e5 + 5, M = 1e9 + 7;

int n, m, a[N], mem[N];

int solve(int i = 0) {
    if (i >= n) return 1e9;
    if (i == n - 1) return 0;

    int &ret = mem[i];
    if (~ret) return ret;

    ret = 1e9;
    for (int j = 1; j <= m && i + j < n; ++j) {
        // Optimize by storing the difference directly
        int cost = a[i] - a[i + j];
        ret = min(ret, solve(i + j) + (cost >= 0 ? cost : -cost));
    }
    return ret;
}

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 0; i < n; ++i)
        scanf("%d", a + i);
    memset(mem, -1, sizeof mem);
    printf("%d", solve());
    return 0;
}

